fn main() uses io, net {
    check fetch("https://API.Example.com./v1") {
        ok a {
            print(a)
        }
        fail w {
            print(w)
        }
    }
    check fetch_status("http://[::1]:8080/x") {
        ok s {
            print(to_text(s))
        }
        fail w {
            print(w)
        }
    }
    check request("GET", "api.example.com:8443/y", "", "{}") {
        ok r {
            print(r)
        }
        fail w {
            print(w)
        }
    }
}
